package com.nelja.urqr.sales.order;
import java.time.Instant; import java.util.*; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Lock; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import jakarta.persistence.LockModeType;
public interface OrderRepository extends JpaRepository<Order,UUID>{Optional<Order> findByIdAndHotelId(UUID id,UUID hotel);@Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select o from Order o where o.id=:id and o.hotelId=:hotel") Optional<Order> findForUpdate(@Param("id")UUID id,@Param("hotel")UUID hotel);@Query("select o from Order o where o.hotelId=:hotel and (:status is null or o.status=:status) and (:from is null or o.createdAt>=:from) and (:to is null or o.createdAt<:to)") Page<Order> search(@Param("hotel")UUID hotel,@Param("status")OrderStatus status,@Param("from")Instant from,@Param("to")Instant to,Pageable pageable);Page<Order> findAllByHotelId(UUID hotel,Pageable p);long countByHotelId(UUID hotel);}
